<template><q-card flat bordered class="table-card"><q-table :pagination="pagination" :rows="rows" :columns="columns" row-key="id" flat :loading="loading" :rows-per-page-options="[5,10,20]" rows-per-page-label="Registros por página" @request="$emit('request',$event)">
  <template #body-cell-codigo="p"><q-td :props="p"><b class="code">{{ p.row.codigo }}</b><div class="muted">{{ p.row.tipoLabel }}</div></q-td></template>
  <template #body-cell-avance="p"><q-td :props="p"><div class="row items-center no-wrap q-gutter-sm"><q-linear-progress rounded :value="p.row.totalProductos ? p.row.contados/p.row.totalProductos : 0" color="green-8" track-color="green-1" size="7px" style="width:75px"/><span>{{ p.row.contados }}/{{ p.row.totalProductos }}</span></div></q-td></template>
  <template #body-cell-diferencias="p"><q-td :props="p"><q-badge :color="p.row.diferencias?'orange-8':'green-7'" :label="p.row.diferencias" /></q-td></template>
  <template #body-cell-estado="p"><q-td :props="p"><q-badge rounded :color="colorEstado(p.row.estado)" :label="textoEstado(p.row.estado)" /></q-td></template>
  <template #body-cell-acciones="p"><q-td :props="p" class="actions-cell"><q-btn flat round dense color="green-8" icon="visibility" @click="$emit('ver',p.row)"><q-tooltip>Ver detalle</q-tooltip></q-btn><q-btn v-if="p.row.estado==='BORRADOR'" flat round dense color="blue-7" icon="edit" @click="$emit('editar',p.row)"><q-tooltip>Editar borrador</q-tooltip></q-btn><q-btn v-if="['BORRADOR','EN_CONTEO'].includes(p.row.estado)" flat round dense color="green-8" icon="playlist_add_check" @click="$emit('contar',p.row)"><q-tooltip>{{ p.row.estado==='BORRADOR'?'Iniciar conteo':'Continuar conteo' }}</q-tooltip></q-btn><q-btn v-if="p.row.estado==='BORRADOR'" flat round dense color="negative" icon="delete" @click="$emit('eliminar',p.row)"><q-tooltip>Eliminar borrador</q-tooltip></q-btn><q-btn v-if="p.row.estado==='EN_REVISION'" flat round dense color="orange-8" icon="rule" @click="$emit('revisar',p.row)"><q-tooltip>Revisar diferencias</q-tooltip></q-btn><q-btn v-if="p.row.estado==='APROBADO'" flat round dense color="red-6" icon="picture_as_pdf" @click="$emit('pdf',p.row)"><q-tooltip>Descargar acta PDF</q-tooltip></q-btn></q-td></template>
  <template #no-data><div class="full-width row flex-center q-pa-xl text-grey-6"><q-icon name="inventory_2" size="42px" class="q-mr-md"/><span>No hay inventarios que coincidan con los filtros.</span></div></template>
  <template #pagination="scope"><div class="row items-center q-gutter-xs"><q-btn round flat dense icon="chevron_left" color="green-8" :disable="scope.isFirstPage" @click="scope.prevPage"/><span class="q-px-sm text-caption">Página {{ pagination.page }}</span><q-btn round flat dense icon="chevron_right" color="green-8" :disable="scope.isLastPage" @click="scope.nextPage"/></div></template>
</q-table></q-card></template>
<script setup>
defineProps({rows:{type:Array,default:()=>[]},loading:Boolean,pagination:{type:Object,required:true}});defineEmits(['ver','editar','eliminar','contar','revisar','pdf','request']);const columns=[{name:'codigo',label:'Código / tipo',field:'codigo',align:'left',sortable:true},{name:'fecha',label:'Fecha',field:'fecha',align:'left',sortable:true},{name:'almacen',label:'Almacén',field:'almacen',align:'left'},{name:'responsable',label:'Responsable',field:'responsable',align:'left'},{name:'avance',label:'Avance',align:'left'},{name:'diferencias',label:'Diferencias',field:'diferencias',align:'center'},{name:'estado',label:'Estado',field:'estado',align:'center',sortable:true},{name:'acciones',label:'Acciones',align:'center'}];const colorEstado=e=>({BORRADOR:'grey-7',EN_CONTEO:'blue-7',EN_REVISION:'amber-8',APROBADO:'green-7',CANCELADO:'red-6'}[e]||'grey-6');const textoEstado=e=>e?.replaceAll('_',' ')||'--'
</script>
<style scoped>.table-card{border-radius:16px;border-color:#dfe7dc;overflow:hidden}:deep(.q-table thead tr){background:#f0f8e9}:deep(.q-table th){font-weight:900;color:#3f5140}.code{color:#356d20}.muted{font-size:11px;color:#7b857c;margin-top:2px}.actions-cell{white-space:nowrap}</style>
